import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const o="/llamatron/assets/swell_editor.bZfvE9PF.svg",g=JSON.parse('{"title":"Swell","description":"","frontmatter":{},"headers":[],"relativePath":"generators/SWELL.md","filePath":"generators/SWELL.md"}'),r={name:"generators/SWELL.md"};function l(i,e,h,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="swell" tabindex="-1">Swell <a class="header-anchor" href="#swell" aria-label="Permalink to &quot;Swell&quot;">​</a></h1><p>Swell scales each note&#39;s velocity, held from 1 to 127, for crescendos and fades. A Swell generator also has an Accent, which makes the beats louder still, up to 50%. Swell is one of the three shapes, each a percentage that ramps from a start to an end, which <a href="./../GENERATORS#shapes">Generators</a> describes: where each is set, which wins, and the settings they share. The Swell percentage runs from 0% to 200%.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+o+'" alt="A Swell generator&#39;s settings, with its Accent"></p><p>The settings are those every shape shares, which <a href="./../GENERATORS#shapes">Generators</a> describes.</p><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Make a Swell generator and add it to a chain, as <code>swell: name</code>, to paint one shape on many clips and change it in one place. A Swell scales the notes on top of the Velocity and the velocity ramps of the scene and the clip, which are the plain way to make one scene louder or to fade one in and out: see <a href="./../SCENES#velocity-and-velocity-ramps">Velocity and Velocity Ramps</a>. In <code>examples/learning/16_bolero_swell.yml</code>, the scenes&#39; velocity ramps make one long crescendo and a Swell generator&#39;s Accent makes the timpani&#39;s downbeats land harder.</p>',7)])])}const w=a(r,[["render",l]]);export{g as __pageData,w as default};
